"""Edge-case tests for model-diagnostics — generated by bug-hunter agent."""

from __future__ import annotations

import numpy as np
import polars as pl
import pytest

import ferrum
from ferrum._diagnostics.source import ModelSource


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


class _PredictOnly:
    """Minimal duck-typed model: predict returns zeros."""

    def predict(self, X):
        return np.zeros(len(X))


class _PredictProba:
    """Model with predict + predict_proba for binary classification."""

    classes_ = np.array([0, 1])

    def predict(self, X):
        return np.zeros(len(X), dtype=int)

    def predict_proba(self, X):
        n = len(X)
        return np.column_stack([np.full(n, 0.8), np.full(n, 0.2)])


class _DecisionFunctionOnly:
    """Binary model that only has decision_function (no predict_proba)."""

    classes_ = np.array([0, 1])

    def predict(self, X):
        return np.zeros(len(X), dtype=int)

    def decision_function(self, X):
        return np.zeros(len(X))


class _NoPredictNoProba:
    """Model with no predict at all."""

    pass


# ---------------------------------------------------------------------------
# 1. Single-row DataFrame — constructor and predictions round-trip
# ---------------------------------------------------------------------------


def test_single_row_predictions_does_not_crash():
    """A 1-row dataset must not cause index errors or panics in predictions()."""
    X = pl.DataFrame({"a": [1.0], "b": [2.0]})
    y = [1.0]
    source = ModelSource(_PredictOnly(), X, y=y)
    pred = source.predictions()
    assert pred.height == 1
    assert "y_true" in pred.columns
    assert "y_pred" in pred.columns
    assert "residual" in pred.columns


# ---------------------------------------------------------------------------
# 2. Empty DataFrame (0 rows)
# ---------------------------------------------------------------------------


def test_zero_row_dataframe_does_not_crash_constructor():
    """ModelSource accepts a 0-row DataFrame without raising on __init__."""
    X = pl.DataFrame({"a": pl.Series([], dtype=pl.Float64)})
    # Must not raise at construction time.
    source = ModelSource(_PredictOnly(), X)
    assert source.X.height == 0


def test_zero_row_predictions_returns_empty_frame():
    """predictions() on a 0-row dataset returns a 0-row DataFrame."""
    X = pl.DataFrame({"a": pl.Series([], dtype=pl.Float64)})
    y = pl.Series("y", [], dtype=pl.Float64)
    source = ModelSource(_PredictOnly(), X, y=y)
    pred = source.predictions()
    assert pred.height == 0
    assert set(pred.columns) >= {"y_true", "y_pred", "residual"}


# ---------------------------------------------------------------------------
# 3. 1D numpy array for X must raise ValueError
# ---------------------------------------------------------------------------


def test_1d_numpy_x_raises_value_error():
    """Passing a 1D ndarray as X must raise ValueError with shape info."""
    with pytest.raises(ValueError, match="2D"):
        ModelSource(_PredictOnly(), np.array([1.0, 2.0, 3.0]), y=[0, 1, 2])


# ---------------------------------------------------------------------------
# 4. Integer numpy array coerces cleanly
# ---------------------------------------------------------------------------


def test_integer_numpy_x_coerces_to_dataframe():
    """X as int64 ndarray must be accepted; no float required."""
    X = np.array([[1, 2], [3, 4], [5, 6]], dtype=np.int64)
    source = ModelSource(_PredictOnly(), X, y=[0, 1, 2])
    assert source.X.height == 3
    assert source.feature_names == ["f0", "f1"]


# ---------------------------------------------------------------------------
# 5. Boolean numpy array as X
# ---------------------------------------------------------------------------


def test_boolean_numpy_x_coerces_without_error():
    """Boolean arrays may appear when features are indicator columns."""
    X = np.array([[True, False], [False, True], [True, True]], dtype=bool)
    source = ModelSource(_PredictOnly(), X, y=[0, 1, 2])
    assert source.X.height == 3


# ---------------------------------------------------------------------------
# 6. y as a single-column polars DataFrame (the DataFrame->Series branch)
# ---------------------------------------------------------------------------


def test_y_as_single_column_polars_dataframe():
    """y passed as a 1-column polars DataFrame must be coerced to a Series."""
    X = pl.DataFrame({"a": [1.0, 2.0, 3.0]})
    y_df = pl.DataFrame({"target": [0.0, 1.0, 0.0]})
    source = ModelSource(_PredictOnly(), X, y=y_df)
    assert source.y is not None
    assert len(source.y) == 3


def test_y_as_multi_column_polars_dataframe_raises():
    """y with >1 column must raise ValueError."""
    X = pl.DataFrame({"a": [1.0, 2.0]})
    y_df = pl.DataFrame({"c1": [0.0, 1.0], "c2": [1.0, 0.0]})
    with pytest.raises(ValueError, match="1 column"):
        ModelSource(_PredictOnly(), X, y=y_df)


# ---------------------------------------------------------------------------
# 7. predictions() when y is None — y_true column is all NaN
# ---------------------------------------------------------------------------


def test_predictions_without_y_produces_nan_y_true():
    """When y=None, predictions() should still return a frame with y_true=NaN."""
    X = pl.DataFrame({"a": [1.0, 2.0, 3.0]})
    source = ModelSource(_PredictOnly(), X)
    pred = source.predictions()
    assert pred.height == 3
    y_true = pred["y_true"].to_numpy()
    assert np.all(np.isnan(y_true)), "y_true should be NaN when y was not provided"


# ---------------------------------------------------------------------------
# 8. probabilities() without predict_proba or decision_function raises
# ---------------------------------------------------------------------------


def test_probabilities_without_proba_or_decision_raises():
    """ModelSource wrapping a predict-only model must raise AttributeError
    from probabilities()."""
    X = pl.DataFrame({"a": [1.0, 2.0], "b": [3.0, 4.0]})
    source = ModelSource(_PredictOnly(), X, y=[0, 1])
    with pytest.raises(AttributeError, match="predict_proba"):
        source.probabilities()


# ---------------------------------------------------------------------------
# 9. probabilities() via decision_function path (sigmoid normalization)
# ---------------------------------------------------------------------------


def test_probabilities_via_decision_function_sums_to_one():
    """Binary model with only decision_function must produce probabilities
    that sum to 1.0 via the sigmoid path."""
    X = pl.DataFrame({"a": [1.0, -1.0, 0.0], "b": [0.5, 0.5, 0.5]})
    source = ModelSource(_DecisionFunctionOnly(), X, y=[0, 1, 0])
    proba = source.probabilities()
    proba_cols = [c for c in proba.columns if c.startswith("proba_")]
    assert len(proba_cols) == 2
    sums = proba.select(proba_cols).to_numpy().sum(axis=1)
    np.testing.assert_allclose(sums, 1.0, atol=1e-10)


# ---------------------------------------------------------------------------
# 10. roc_curve() when y is None must raise ValueError with clear message
# ---------------------------------------------------------------------------


def test_roc_curve_without_y_raises():
    """roc_curve() requires y; calling without it must raise ValueError."""
    X = pl.DataFrame({"a": [1.0, 2.0, 3.0]})
    source = ModelSource(_PredictProba(), X)
    with pytest.raises(ValueError, match="requires y"):
        source.roc_curve()


