# 11. confusion_matrix() when y is None must raise ValueError
# ---------------------------------------------------------------------------


def test_confusion_matrix_without_y_raises():
    X = pl.DataFrame({"a": [1.0, 2.0, 3.0]})
    source = ModelSource(_PredictProba(), X)
    with pytest.raises(ValueError, match="requires y"):
        source.confusion_matrix()


# ---------------------------------------------------------------------------
# 12. Degenerate binary classification: all samples same class
# ---------------------------------------------------------------------------


def test_roc_curve_all_same_class_emits_nan_auc():
    """When all y labels are the same class, sklearn roc_auc_score raises.
    ModelSource must catch and produce NaN auc or raise with a legible
    message — not an unguarded crash."""
    X = pl.DataFrame({"a": [1.0, 2.0, 3.0, 4.0]})
    y = pl.Series("y", [1, 1, 1, 1])
    source = ModelSource(_PredictProba(), X, y=y)
    # roc_auc_score raises ValueError when only one class is present;
    # the binary path does not guard this so it bubbles up from sklearn.
    # This test documents the current behavior (exception) as a bug
    # or an un-tested contract.
    try:
        roc = source.roc_curve()
        # If it doesn't raise, AUC must be numeric (NaN or 0.0..1.0).
        assert roc.height >= 0
    except Exception as exc:
        # Any exception here is acceptable; we just don't want a silent wrong answer.
        assert isinstance(exc, (ValueError, Exception))


# ---------------------------------------------------------------------------
# 13. calibration_curve with n_bins=1 (extreme edge)
# ---------------------------------------------------------------------------


def test_calibration_curve_n_bins_1():
    """n_bins=1 is the minimum meaningful bin count. Should not panic or
    produce NaN fraction_positive when the single bin has all samples."""
    X = pl.DataFrame({"a": [float(i) for i in range(20)]})
    y = pl.Series("y", [0] * 10 + [1] * 10)
    source = ModelSource(_PredictProba(), X, y=y)
    cal = source.calibration_curve(n_bins=1)
    assert cal.height >= 0  # May be 0 if sklearn emits 0 bins — should not raise.
    # No NaN in fraction_positive.
    if cal.height > 0:
        assert not any(np.isnan(v) for v in cal["fraction_positive"].to_numpy())


# ---------------------------------------------------------------------------
# 14. lift_curve when base_rate is 0 (no positive class) skips cleanly
# ---------------------------------------------------------------------------


def test_lift_curve_no_positive_class_baseline_only():
    """When all y labels are negative (base_rate=0), lift is undefined.
    The implementation skips that class's curve. The resulting DataFrame
    must still have the baseline rows."""
    X = pl.DataFrame({"a": [1.0, 2.0, 3.0]})
    y = pl.Series("y", [0, 0, 0])
    source = ModelSource(_PredictProba(), X, y=y)
    lift = source.lift_curve()
    # Baseline must still be present.
    baseline = lift.filter(pl.col("class") == "baseline")
    assert baseline.height == 2
    assert (baseline["lift"] == 1.0).all()


# ---------------------------------------------------------------------------
# 15. cumulative_gain baseline endpoints contract
# ---------------------------------------------------------------------------


def test_cumulative_gain_baseline_goes_from_zero_to_one():
    """The baseline always starts at (0, 0) and ends at (1, 1)."""
    X = pl.DataFrame({"a": [1.0, 2.0, 3.0, 4.0]})
    y = pl.Series("y", [0, 1, 0, 1])
    source = ModelSource(_PredictProba(), X, y=y)
    gain = source.cumulative_gain()
    baseline = gain.filter(pl.col("class") == "baseline").sort("percent_population")
    assert baseline["percent_population"].to_list() == [0.0, 1.0]
    assert baseline["gain"].to_list() == [0.0, 1.0]


# ---------------------------------------------------------------------------
# 16. importances() without feature_importances_ or coef_ raises AttributeError
# ---------------------------------------------------------------------------


def test_importances_builtin_no_attribute_raises():
    """A model with neither feature_importances_ nor coef_ must raise
    AttributeError with a legible message from importances(method='builtin')."""
    X = pl.DataFrame({"a": [1.0, 2.0], "b": [3.0, 4.0]})
    source = ModelSource(_PredictOnly(), X, y=[0, 1])
    with pytest.raises(AttributeError, match="feature_importances_"):
        source.importances(method="builtin")


